\documentclass[11pt]{article}
\usepackage{amsmath}
\title{Estimating the Time-Varying Reproduction Number\\
during a Measles Outbreak in a Partially Vaccinated District}
\author{A. Ebersole and T. Ngaita}
\date{May 2026}

\begin{document}
\maketitle

\section{Background}
Between January and April 2026 the district health office recorded
214 laboratory-confirmed measles cases, mostly among children under
ten years of age.
Routine two-dose coverage in the affected subcounties had fallen from
92\% in 2019 to 81\% in 2024, and supplementary immunisation
activities were postponed twice during the same period.

\section{Data}
Line-list entries include date of rash onset, date of report, age,
vaccination status, and subcounty of residence.
We excluded nine entries with implausible onset dates and six entries
duplicated across reporting facilities.
The final analysis set contains 199 cases with complete onset data.

\section{Transmission Dynamics}
We reconstructed the daily incidence series from onset dates and
applied a renewal-equation estimator with a serial interval of
11.7 days (standard deviation 2.0 days).
The effective reproduction number $R_0_t$ fluctuated between 0.4 and
2.1 over the study window, with the highest values concentrated in the
three weeks preceding the school closure order.

\section{Epidemic Curve}
\begin{figure}[t]
\centering
\fbox{\rule{0pt}{35mm}\rule{60mm}{0pt}}
\caption{Daily counts of rash onset by report date\footnote{Six cases
with missing onset dates were assigned by multiple imputation under a
lognormal delay model.}.}
\label{fig:curve}
\end{figure}
Figure~\ref{fig:curve} shows a bimodal curve whose second peak follows
the return to school after the midterm break.

\section{Findings}
The \textb{attack rate} was highest in the 5--9 year age band
(14.2 per 1{,}000), and no cases were reported among fully vaccinated
adults.
Estimates were insensitive to the choice of serial interval
distribution within the plausible range.

\section{Response}
A reactive vaccination campaign began in week 14 and reached
approximately 31{,}000 children within three weeks.
The campaign prioritised:
\begin{itemize}
\item subcounties with two-dose coverage below 85\%;
\item schools with two or more linked cases;
\item informal settlements identified in the microplan.
\end{itemize}
The incidence fell below one case per day by week 19.

\section{Conclusion}
Sustained estimation of time-varying transmission intensity gave the
response team a quantitative trigger for escalating interventions,
and the same pipeline now runs weekly on routine surveillance data.

\end{document}

